#!/usr/bin/env python3
from __future__ import annotations

from pathlib import Path
import re
import subprocess

ROOT = Path(__file__).resolve().parents[1]


def path(rel: str) -> Path:
    return ROOT / rel


def read(rel: str) -> str:
    return path(rel).read_text(encoding="utf-8")


def write(rel: str, text: str) -> None:
    path(rel).write_text(text, encoding="utf-8")


def replace_once(rel: str, old: str, new: str) -> None:
    text = read(rel)
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{rel}: expected one exact match, found {count}: {old[:120]!r}")
    write(rel, text.replace(old, new, 1))


def replace_all(rel: str, old: str, new: str, minimum: int = 1) -> None:
    text = read(rel)
    count = text.count(old)
    if count < minimum:
        raise RuntimeError(f"{rel}: expected at least {minimum} matches, found {count}: {old[:120]!r}")
    write(rel, text.replace(old, new))


def regex_once(rel: str, pattern: str, replacement: str) -> None:
    text = read(rel)
    new, count = re.subn(pattern, replacement, text, count=1, flags=re.MULTILINE)
    if count != 1:
        raise RuntimeError(f"{rel}: regex expected one match, found {count}: {pattern}")
    write(rel, new)


def insert_before(rel: str, marker: str, addition: str) -> None:
    replace_once(rel, marker, addition + marker)


def run(*args: str, check: bool = True) -> None:
    print("+", " ".join(args), flush=True)
    subprocess.run(args, cwd=ROOT, check=check)


